<?php
declare(strict_types=1);require_once __DIR__.'/../shared/bootstrap.php';require_once __DIR__.'/../shared/owner-auth.php';method('POST');same_origin();limit('owner-api',90,60);$d=body();$a=clean($_GET['action']??'',30);
if($a==='session'){reply(200,['ok'=>true,'authenticated'=>(bool)owner_user(),'username'=>owner_user()['username']??'','csrf'=>owner_csrf()]);}
if($a==='login'){$u=clean($d['username']??'',80);$pw=is_string($d['password']??null)?$d['password']:'';$q=db()->prepare('SELECT id,username,password_hash FROM owner_users WHERE username=? LIMIT 1');$q->execute([$u]);$r=$q->fetch();if(!$r||$pw===''||strlen($pw)>200||!password_verify($pw,$r['password_hash'])){usleep(250000);reply(401,['ok'=>false,'message'=>'Invalid username or password.']);}session_regenerate_id(true);$_SESSION['owner_id']=(int)$r['id'];$_SESSION['owner_username']=$r['username'];$_SESSION['owner_csrf']=bin2hex(random_bytes(32));db()->prepare('UPDATE owner_users SET last_login_at=UTC_TIMESTAMP() WHERE id=?')->execute([(int)$r['id']]);reply(200,['ok'=>true,'authenticated'=>true,'username'=>$r['username'],'csrf'=>owner_csrf()]);}
if($a==='logout'){owner_require();owner_check_csrf($d);$_SESSION=[];if(ini_get('session.use_cookies')){$c=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$c['path'],$c['domain'],$c['secure'],$c['httponly']);}session_destroy();reply(200,['ok'=>true]);}owner_require();owner_check_csrf($d);$p=db();
if($a==='orders'){$q=$p->query('SELECT o.id,o.order_number,o.status,o.fulfillment,o.payment_method,o.address,o.customer_latitude,o.customer_longitude,o.delivery_boy_name,o.delivery_boy_phone,o.delivery_notes,o.preferences,o.subtotal,o.delivery_fee,o.packaging_fee,o.distance_km,o.total,o.created_at,c.name customer_name,c.phone,c.email FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.id DESC LIMIT 100');$orders=$q->fetchAll();$ids=array_column($orders,'id');$map=[];if($ids){$it=$p->prepare('SELECT order_id,item_name,unit_price,quantity,line_total FROM order_items WHERE order_id IN ('.implode(',',array_fill(0,count($ids),'?')).') ORDER BY id');$it->execute($ids);foreach($it->fetchAll() as $i)$map[$i['order_id']][]=$i;}foreach($orders as &$o)$o['items']=$map[$o['id']]??[];unset($o);reply(200,['ok'=>true,'orders'=>$orders]);}
if($a==='menu')reply(200,['ok'=>true,'items'=>$p->query('SELECT id,name,variant,category,description,price,emoji,is_available,sort_order FROM menu_items ORDER BY sort_order,id')->fetchAll()]);
if($a==='assign_delivery'){$id=filter_var($d['order_id']??null,FILTER_VALIDATE_INT);$name=clean($d['delivery_boy_name']??'',100);$ph=phone($d['delivery_boy_phone']??'');$notes=clean($d['delivery_notes']??'',500);if(!$id||$name===''||strlen(preg_replace('/\\D/','',$ph)??'')<10)reply(422,['ok'=>false,'message'=>'Enter delivery person name and a valid mobile number.']);$q=$p->prepare("UPDATE orders SET delivery_boy_name=?,delivery_boy_phone=?,delivery_notes=?,status=IF(status IN ('Received','Accepted','Preparing','Ready'),'Out for delivery',status),updated_at=UTC_TIMESTAMP() WHERE id=? AND fulfillment='Delivery'");$q->execute([$name,$ph,$notes,$id]);if(!$q->rowCount())reply(422,['ok'=>false,'message'=>'Delivery order not found or details were unchanged.']);reply(200,['ok'=>true]);}
if($a==='status'){$n=clean($d['order_number']??'',32);$s=clean($d['status']??'',30);if($n===''||!in_array($s,['Received','Accepted','Preparing','Ready','Out for delivery','Completed','Cancelled'],true))reply(422,['ok'=>false,'message'=>'Invalid order status.']);$q=$p->prepare('UPDATE orders SET status=?,updated_at=UTC_TIMESTAMP() WHERE order_number=?');$q->execute([$s,$n]);if(!$q->rowCount()){$q=$p->prepare('SELECT id FROM orders WHERE order_number=?');$q->execute([$n]);if(!$q->fetch())reply(404,['ok'=>false,'message'=>'Order not found.']);}reply(200,['ok'=>true]);}
if($a==='toggle'){$id=filter_var($d['id']??null,FILTER_VALIDATE_INT);if(!$id)reply(422,['ok'=>false,'message'=>'Invalid menu item.']);$q=$p->prepare('UPDATE menu_items SET is_available=IF(is_available=1,0,1) WHERE id=?');$q->execute([$id]);if(!$q->rowCount())reply(404,['ok'=>false,'message'=>'Menu item not found.']);reply(200,['ok'=>true]);}
if($a==='save_menu'){$id=filter_var($d['id']??0,FILTER_VALIDATE_INT);$n=clean($d['name']??'',140);$variant=clean($d['variant']??'Single',30)?:'Single';$c=clean($d['category']??'',50);$desc=clean($d['description']??'',500);$emoji=clean($d['emoji']??'🍽️',20);$price=filter_var($d['price']??null,FILTER_VALIDATE_FLOAT);$sort=filter_var($d['sort_order']??0,FILTER_VALIDATE_INT);if($n===''||$c===''||$price===false||$price<=0||$price>999999||$sort===false||$sort<0)reply(422,['ok'=>false,'message'=>'Enter a name, category, valid price and sort order.']);if($id){$q=$p->prepare('UPDATE menu_items SET name=?,variant=?,category=?,description=?,price=?,emoji=?,sort_order=? WHERE id=?');$q->execute([$n,$variant,$c,$desc,$price,$emoji?:'🍽️',$sort,$id]);if(!$q->rowCount()){$q=$p->prepare('SELECT id FROM menu_items WHERE id=?');$q->execute([$id]);if(!$q->fetch())reply(404,['ok'=>false,'message'=>'Menu item not found.']);}}else $p->prepare('INSERT INTO menu_items(name,variant,category,description,price,emoji,sort_order) VALUES(?,?,?,?,?,?,?)')->execute([$n,$variant,$c,$desc,$price,$emoji?:'🍽️',$sort]);reply(200,['ok'=>true]);}reply(404,['ok'=>false,'message'=>'Unknown action.']);